 function openEditor(kind,id){if(!id&&kind!=='projects'&&kind!=='facts'&&!state.projects.length){toast('Cadastre uma obra primeiro.');return openEditor('projects')}let record=['budgets','schedule'].includes(kind)?getS(id):kind==='projects'?(id?getP(id):defaults(kind)):id?state[kind].find(x=>x.id===id):defaults(kind);if(!record)return toast('Registro não encontrado.');if(photoEditor){photoEditor.dispose();photoEditor=null}record=D.clone(record);if(kind==='diary')record.staffText=(record.staff||[]).map(r=>[r.role,r.quantity,r.company,r.hours].join(' | ')).join('\n');if(kind==='budgets')D.CATEGORIES.forEach((c,i)=>record['budget'+i]=record.budgets[c]);if(kind==='schedule')record.months.forEach((x,i)=>record['month'+i]=x*100);let specs=schema(kind,record);editContext={kind,id:record.id,record,specs};$('#removeRecord').hidden=!state[kind]?.some(r=>r.id===record.id);$('#dialogTitle').textContent={activities:'Planejar / atualizar serviço',budgets:'Definir verbas da etapa',schedule:'Reprogramar distribuição mensal',projects:'Configurar '+record.name,tasks:'Tarefa do engenheiro',issues:'Pendência / risco',checklists:'Conferência de execução',costs:'Contratação / pagamento',quotes:'Cotação',materials:'Insumo e necessidade',stockMoves:'Movimentação de estoque',measurements:'Item de medição',receipts:'Recebimento efetivo',diary:'Registro diário interno',teams:'Equipe'}[kind]||'Editar';$('#dialogEyebrow').textContent=kind==='projects'?projectLabel(record):(record.project?projectLabel(record.project):'Cadastro');$('#fields').innerHTML=specs.map(f=>{let val=record[f.key]??'',attrs=`name="${h(f.key)}" id="field-${h(f.key)}" ${f.required?'required':''} ${f.readonly?'readonly':''}`,control;if(f.type==='textarea')control=`<textarea ${attrs}>${h(val)}</textarea>`;else if(f.type==='select'||f.type==='multi')control=`<select ${attrs} ${f.type==='multi'?'multiple size="7"':''}>${f.type==='multi'?'':'<option value="">Selecionar…</option>'}${(f.options||[]).map(([v,t])=>`<option value="${h(v)}" ${(Array.isArray(val)?val.includes(v):String(val)===String(v))?'selected':''}>${h(t)}</option>`).join('')}</select>`;else control=`<input ${attrs} type="${h(f.type)}" value="${h(val)}" ${f.type==='number'?`min="${f.min??0}" step="${f.step||'any'}"`:''}>`;return `<div class="field ${f.full?'full':''}"><label for="field-${h(f.key)}">${h(f.label)}</label>${control}${f.hint?`<small>${h(f.hint)}</small>`:''}</div>`}).join('');$('#formError').textContent='';if(kind==='documents')documentEditor(record);if(kind==='diary'&&window.ObrasPhotos){$('#fields').innerHTML+='<section id="diaryPhotos" class="diary-photo-editor field full"></section>';photoEditor=window.ObrasPhotos.attachEditor($('#diaryPhotos'),record.photos||[])}$('#editor').showModal();let pf=$('#field-project');if(pf){pf.addEventListener('change',()=>filterRelated(pf.value));filterRelated(pf.value)}}
 function filterRelated(p){for(let key of ['stage','activity','material','parent']){let sel=$('#field-'+key);if(!sel)continue;for(let option of [...sel.options]){if(!option.value)continue;let rec=(key==='stage'||key==='parent')?getS(option.value):key==='activity'?getA(option.value):state.materials.find(m=>m.id===option.value);option.hidden=rec?.project!==p;option.disabled=rec?.project!==p}if(sel.selectedOptions[0]?.disabled)sel.value=''}}
 $('#editForm').addEventListener('submit',async e=>{e.preventDefault();if(submitting)return;submitting=true;let saving=editContext,controller=photoEditor,submitButton=$('#editForm button[type="submit"]');if(submitButton)submitButton.disabled=true;try{let {kind,record,specs}=editContext,x=D.clone(record);for(let f of specs){if(f.readonly)continue;let el=$('#field-'+f.key);let v=f.type==='multi'?[...el.selectedOptions].map(o=>o.value):el.value.trim();if(f.type==='number'){v=v===''?(f.nullable?null:0):Number(v);if(v!==null&&!Number.isFinite(v))throw Error('Número inválido: '+f.label)}x[f.key]=v}if(kind==='diary'){x.staff=(x.staffText||'').split('\n').filter(r=>r.trim()).map(line=>{let [role,quantity,company,hours]=line.split('|').map(x=>x.trim());return {role,quantity,company,hours}});if(controller)x.photos=controller.getMetadata()}let next;
  if(kind==='budgets'){next=D.clone(state);let target=next.stages.find(s=>s.id===record.id);D.CATEGORIES.forEach((c,i)=>target.budgets[c]=x['budget'+i]);target.remainingCost=x.remainingCost;if(D.CATEGORIES.some(c=>target.budgets[c]!==null&&target.budgets[c]<0)||x.remainingCost!==null&&x.remainingCost<0)throw Error('Custos devem ser não negativos.');audited(next,'stages',record.id,record,{...target,note:x.note})}
  else if(kind==='schedule'){let months=Array.from({length:12},(_,i)=>x['month'+i]/100);if(months.some(v=>v<0||v>1)||Math.abs(D.sum(months,v=>v)-1)>.00001)throw Error('A distribuição deve somar 100%, com percentuais entre zero e 100.');if(!x.note)throw Error('Registre o motivo / aprovação da reprogramação.');next=D.clone(state);next.stages.find(s=>s.id===record.id).months=months;audited(next,'schedule',record.id,record.months,{months,note:x.note})}
  else if(kind==='projects'){if(!x.name.trim())throw Error('Informe o nome da obra.');x.code=x.code.trim()||window.EngefexManager.nextProjectCode(state.projects);if(state.projects.some(p=>p.id!==x.id&&String(p.code||'').toUpperCase()===x.code.toUpperCase()))throw Error('Já existe uma obra com esse código. Escolha outro.');if(x.initialCash!==null&&x.initialCash<0)throw Error('Saldo inicial deve ser não negativo.');next=D.clone(state);next.projects=next.projects.filter(p=>p.id!==x.id).concat(x);audited(next,'projects',x.id,record,x)}
  else if(['stages','facts','documents'].includes(kind)){if(kind==='documents')x.attachments=await commitDocuments();next=window.EngefexManager.save(state,kind,x)}else {if(kind==='issues'&&x.status==='Resolvida'&&!x.resolution)throw Error('Informe a resolução para encerrar a pendência.');if(kind==='checklists'&&x.status!=='Pendente'&&!x.evidence)throw Error('Registre evidência ou justificativa da conferência.');if(kind==='tasks'&&x.status==='Concluída'&&x.blocker)throw Error('Resolva ou retire o impedimento antes de concluir a tarefa.');next=D.saveRecord(state,kind,x)}if(kind==='diary'&&controller){await controller.commit();if(editContext!==saving)throw Error('O formulário mudou. Salve novamente o registro aberto.')}next=window.EngefexManager.reconcile(next);persist(next);$('#editor').close();if(controller)controller.dispose();photoEditor=null;render()}catch(err){$('#formError').textContent=err.message}finally{submitting=false;if(submitButton)submitButton.disabled=false}});
 function settings(){let content=`<div class="reader-page"><h3>Configurar cada obra</h3>${button('new:projects','+ Nova obra','primary')}<p class="section-note">Dados, valores, responsáveis e prazos de cada obra podem ser editados.</p>${state.projects.map(p=>`<div class="project-card"><h3>${h(projectLabel(p))}</h3><p>${h(p.location)}</p><div class="split-line"><span>Valor contratado</span><strong>${money(p.value)}</strong></div><div class="split-line"><span>Início / OIS</span><span>${fmt(p.start)} / ${fmt(p.orderDate)}</span></div><div class="split-line"><span>Conclusão pela OS + ${p.referenceDays||'prazo a definir'} dias</span><span>${p.orderDate&&p.referenceDays?fmt(D.addDays(p.orderDate,p.referenceDays)):'OIS pendente'}</span></div><div class="split-line"><span>Referência de início (registre a regra no contrato)</span><span>${p.start?fmt(p.start):'A definir'}</span></div><div class="split-line"><span>Contrato / observações</span><span>${h(p.contract||'A definir')}</span></div>${edit('projects',p.id,'Configurar obra')}</div>`).join('')}<h3 style="margin-top:25px">Dados e portabilidade</h3><p class="section-note">Os registros ficam neste navegador e endereço. O aplicativo funciona sem conta ou conexão externa. Backup JSON leva os registros, o histórico e as fotos anexadas ao diário. PDFs e imagens não anexadas permanecem nos arquivos originais. O histórico registra os valores anteriores e posteriores de cada alteração. Ele não substitui o arquivo de backup.</p><div class="actions">${button('backup','Exportar backup','primary')}${button('import','Importar backup','secondary')}${button('print','Imprimir página','secondary')}</div><p class="section-note">Para GitHub Pages, publique o conteúdo de dist. Não há sincronização entre dispositivos. O aplicativo está preparado para hospedagem estática, mas um servidor com banco e autenticação será necessário para uso compartilhado. A publicação não ocorre por este botão.</p></div>`;$('#readerTitle').textContent='Configurações';$('#readerContent').innerHTML=content;$('#reader').showModal()}
 function docReader(id){let d=state.documents.find(x=>x.id===id);$('#readerTitle').textContent=d.name;$('#readerContent').innerHTML=`<div class="reader-toolbar"><input id="docSearch" placeholder="Buscar no texto deste PDF" aria-label="Buscar no documento"><button class="button secondary" data-pdf="${id}">Abrir original</button></div><div id="docPages"></div>`;function pages(term=''){let found=d.textPages.map((text,i)=>({text,i})).filter(x=>!term||x.text.toLocaleLowerCase('pt-BR').includes(term.toLocaleLowerCase('pt-BR')));$('#docPages').innerHTML=found.length?found.map(x=>`<article class="reader-page"><h3>${h(id)} · Página ${x.i+1}</h3><pre>${h(x.text.trim()||'Sem texto extraível. Abra o PDF e confira visualmente.')}</pre></article>`).join(''):'<div class="empty">Nenhuma página com esse termo.</div>'}pages(search);$('#docSearch').value=search;$('#docSearch').oninput=e=>pages(e.target.value);$('#reader').showModal()}
 function openPDF(id){if(!files.has(id)){toast('Selecione a pasta extraída do ZIP para vincular os PDFs originais.');$('#documentFolder').click();return}let u=URL.createObjectURL(files.get(id));window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),120000)}
 document.addEventListener('click',e=>{let el=e.target.closest('[data-action],[data-edit],[data-tab],[data-doc],[data-pdf],[data-docx],[data-view-photos],[data-view],[data-remove]');if(!el)return;if(el.dataset.view)return viewRecord(el.dataset.view,el.dataset.id);if(el.dataset.remove)return removeItem(el.dataset.remove,el.dataset.id);if(el.dataset.docx)return generateDocx(el.dataset.docx,el);if(el.dataset.viewPhotos)return viewPhotos(el.dataset.viewPhotos);if(el.dataset.edit){if($('#reader').open)$('#reader').close();return openEditor(el.dataset.edit,el.dataset.id)}if(el.dataset.tab){tab[el.dataset.tab]=el.dataset.value;search='';filter='';render();return}if(el.dataset.doc)return docReader(el.dataset.doc);if(el.dataset.pdf)return openPDF(el.dataset.pdf);let action=el.dataset.action;if(action==='budget-import')return openBudgetImport();if(action?.startsWith('document-file:'))return documentFile(action.slice(14));if(action==='confirm-budget')return confirmBudgetImport();if(action?.startsWith('new:'))return openEditor(action.slice(4));if(action==='csv')return csv();if(action==='settings')return settings();if(action==='folder')return $('#documentFolder').click();if(action==='backup')return exportBackup();if(action==='import')return $('#importFile').click();if(action==='print')return window.print()});

 async function generateDocx(id,trigger){let record=state.diary.find(x=>x.id===id);if(!record)return toast('Registro não encontrado.');if(!window.docx||!window.ObrasDiaryDocx)return toast('O gerador ainda não carregou. Atualize a página com internet e tente novamente.');if(trigger)trigger.disabled=true;try{toast('Preparando DOCX com as fotos…');let photos=window.ObrasPhotos?await window.ObrasPhotos.load(record.photos||[]):[];let project=getP(record.project),logoResponse=await fetch('engefex-logo.png');if(!logoResponse.ok)throw Error('Logotipo indisponível.');let logo=new Uint8Array(await logoResponse.arrayBuffer()),doc=window.ObrasDiaryDocx.createDocument(window.docx,{project,record,photos,logo}),blob=await window.docx.Packer.toBlob(doc);download(window.ObrasDiaryDocx.filename(project,record),blob,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');toast('DOCX gerado com '+photos.length+' foto(s).')}catch(err){toast('Não foi possível gerar o DOCX: '+err.message)}finally{if(trigger)trigger.disabled=false}}
 async function viewPhotos(id){let record=state.diary.find(x=>x.id===id);if(!record)return;$('#readerTitle').textContent='Fotos do diário · '+projectLabel(record.project)+' · '+fmt(record.date);$('#readerContent').innerHTML='<div class="empty">Carregando fotos…</div>';$('#reader').showModal();try{let photos=window.ObrasPhotos?await window.ObrasPhotos.load(record.photos||[]):[];$('#readerContent').innerHTML=photos.length?'<div class="saved-photo-gallery">'+photos.map((p,i)=>'<figure><img src="'+p.dataURL+'" alt="'+h(p.caption||p.name)+'"><figcaption><strong>Foto '+(i+1)+'</strong> '+h(p.caption||p.name)+'</figcaption></figure>').join('')+'</div>':'<div class="empty">Este registro ainda não tem fotos. Use Editar → Adicionar fotos.</div>'}catch(err){$('#readerContent').innerHTML='<div class="empty red-text">'+h(err.message)+'</div>'}}
 async function exportBackup(){try{toast('Preparando backup com fotos…');let snapshot=D.clone(state),bundle=window.ObrasPhotos?await window.ObrasPhotos.backup(snapshot):snapshot;bundle.fileFiles=await window.LocalFiles.load(window.LocalFiles.refs(snapshot));download('backup-engefex-'+D.today()+'.json',JSON.stringify(bundle,null,2));toast('Backup exportado com os registros e as fotos do diário.')}catch(err){toast(err.message)}}
 $('#removeRecord').onclick=()=>{if(submitting)return toast('Aguarde o salvamento.');try{if(!editContext||!confirm('Remover este lançamento do controle? O registro anterior ficará preservado no histórico.'))return;let next=D.removeRecord(state,editContext.kind,editContext.id);persist(next);$('#editor').close();render()}catch(e){$('#formError').textContent=e.message}};$('#backup').onclick=exportBackup;$('#settings').onclick=settings;$('#closeDialog').onclick=$('#cancelDialog').onclick=()=>{if(submitting)return toast('Aguarde o salvamento.');$('#editor').close()};$('#editor').addEventListener('cancel',e=>{if(submitting)e.preventDefault()});$('#closeReader').onclick=()=>$('#reader').close();$('#menuToggle').onclick=()=>$('.sidebar').classList.toggle('open');
 $('#project').onchange=e=>{if(diaryDirty&&!confirm('Trocar de obra sem salvar o diário?')){e.target.value=project;return}diaryDirty=false;project=e.target.value;search='';filter='';try{localStorage.setItem(UIKEY,JSON.stringify({project}))}catch{}render()};
 $('#importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let x=JSON.parse(await file.text());if(x.state)x=window.EngefexManager.fromGenericBackup(x);D.backupValid(x);if(!confirm('Substituir os dados deste navegador pelo backup selecionado? Exporte os dados atuais antes de continuar.'))return;x=await window.EngefexManager.restoreFiles(x);if(window.ObrasPhotos)x=await window.ObrasPhotos.importBackup(x);let prior=storageError;storageError='';try{persist(x,'Backup importado com sucesso.')}catch(err){storageError=prior;throw err}$('#reader').close();render()}catch(err){toast('Não foi possível importar: '+err.message)}finally{e.target.value=''}};
 $('#documentFolder').onchange=e=>{let list=[...e.target.files];for(let d of state.documents){let file=list.find(f=>f.name===d.name&&((f.webkitRelativePath||'').includes(d.lot==='L01'?'Lote 1':d.lot==='L02'?'Lote 2':'')||d.lot==='Geral'))||list.find(f=>f.name===d.name);if(file)files.set(d.id,file)}toast(files.size+' PDFs vinculados para consulta nesta sessão.');render()};
 window.addEventListener('hashchange',()=>{search='';filter='';$('.sidebar').classList.remove('open');render();window.scrollTo(0,0)});
 function projectsPage(){return head('Obras','Cadastre e acompanhe quantas obras precisar.',button('new:projects','+ Nova obra')+button('budget-import','Importar orçamento','secondary'))+table(['Obra','Cliente / local','Valor contratado','Início / prazo','Situação',''],state.projects.map(p=>`<tr><td><strong>${h(p.name)}</strong><br><small>${h(p.code)}</small></td><td>${h(p.client)}<br>${h(p.location)}</td><td class="num">${money(p.value)}</td><td>${fmt(p.start)}<br>${p.referenceDays?qty(p.referenceDays)+' dias':'Prazo a definir'}</td><td>${pill(p.state)}</td><td>${edit('projects',p.id)}</td></tr>`).join(''),'Cadastre sua primeira obra para começar.')}
 function viewRecord(kind,id){let target=['budgets','schedule'].includes(kind)?'stages':kind,r=state[target]?.find(r=>r.id===id);if(!r)return toast('Registro não encontrado.');$('#readerTitle').textContent=r.name||r.title||r.description||'Visualizar registro';let specs=schema(target,r),seen=new Set(specs.map(f=>f.key));$('#readerContent').innerHTML='<div class="reader-page"><dl class="record-details">'+specs.map(f=>{let value=r[f.key];if(f.type==='select'||f.type==='multi'){let options=f.options||[];value=Array.isArray(value)?value.map(v=>options.find(x=>x[0]===v)?.[1]||v).join(', '):options.find(x=>x[0]===value)?.[1]||value}return '<div><dt>'+h(f.label)+'</dt><dd>'+br(typeof value==='object'?JSON.stringify(value):value??'A definir')+'</dd></div>'}).join('')+'</dl><details><summary>Dados completos do registro</summary><pre class="record-json">'+h(JSON.stringify(r,null,2))+'</pre></details><div class="actions">'+edit(target,id)+(kind==='diary'?'<button class="button secondary" data-docx="'+h(id)+'">Gerar DOCX</button><button class="text-btn" data-view-photos="'+h(id)+'">Abrir fotos</button>':'')+'</div></div>';$('#reader').showModal()}
 function removeItem(kind,id){if(!confirm('Excluir este registro? Se for uma obra ou etapa, os cadastros dependentes também serão removidos. A alteração ficará registrada no histórico. Exporte um backup antes de exclusões amplas.'))return;try{persist(D.removeRecord(state,kind,id));if($('#reader').open)$('#reader').close();if($('#editor').open)$('#editor').close();render()}catch(e){toast(e.message)}}
 let budgetSheets=[],budgetAnalysis=null;
 function openBudgetImport(){if(!state.projects.length){toast('Cadastre uma obra primeiro.');return openEditor('projects')}if(project==='all')return toast('Selecione a obra de destino no topo antes de importar o orçamento.');budgetSheets=[];budgetAnalysis=null;$('#readerTitle').textContent='Importar orçamento Excel';$('#readerContent').innerHTML='<div class="reader-page"><p>Destino: <strong>'+h(getP(project).name)+'</strong>. A importação adiciona etapas e serviços e mantém todos os campos editáveis.</p><label>Arquivo .xlsx<input id="budgetSelect" type="file" accept=".xlsx"></label><label>Aba<select id="budgetSheet"></select></label><label class="inline-check"><input id="budgetSwap" type="checkbox"> Inverter quantidade e unidade</label><label class="inline-check"><input id="budgetValue" type="checkbox"> Atualizar o valor contratado da obra com o total geral do arquivo</label><div id="budgetPreview"></div><div class="actions">'+button('confirm-budget','Confirmar importação')+'</div></div>';$('#reader').showModal();$('#readerContent [data-action="confirm-budget"]').disabled=true;$('#budgetSelect').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('Limite do arquivo: 20 MB.');budgetAnalysis=null;$('#readerContent [data-action="confirm-budget"]').disabled=true;$('#budgetPreview').textContent='Lendo planilha…';budgetSheets=await BudgetImport.readWorkbook(await f.arrayBuffer());$('#budgetSheet').innerHTML=budgetSheets.map((s,i)=>'<option value="'+i+'">'+h(s.name)+'</option>').join('');drawBudgetPreview()}catch(err){$('#budgetPreview').textContent=err.message}};$('#budgetSheet').onchange=$('#budgetSwap').onchange=drawBudgetPreview;}
 function drawBudgetPreview(){let sheet=budgetSheets[Number($('#budgetSheet').value)];if(!sheet)return;budgetAnalysis=BudgetImport.analyze(sheet,$('#budgetSwap').checked);let a=budgetAnalysis;$('#budgetPreview').innerHTML='<h3>'+a.stages.length+' etapas / subetapas · '+a.services.length+' serviços</h3><p>Unidade: coluna '+a.mapping.unit+' · Quantidade: coluna '+a.mapping.quantity+'<br>Soma dos serviços: '+money(a.sum)+'<br>Tributos: '+money(a.controls.tax)+'<br>Total geral: '+money(a.controls.total)+'</p>'+(a.errors.length?'<div class="notice red-text">'+a.errors.map(h).join('<br>')+'</div>':'')+(a.warnings.length?'<div class="notice">'+a.warnings.map(h).join('<br>')+'</div>':'')+table(['Código','Serviço','Quantidade','Total'],a.services.map(r=>'<tr><td>'+h(r.code)+'</td><td>'+h(r.name)+'</td><td>'+qty(r.quantity)+' '+h(r.unit)+'</td><td>'+money(r.total)+'</td></tr>').join(''))+'<p class="section-note">Fórmulas são lidas pelo último resultado salvo no Excel. Os unitários de mão de obra, materiais e equipamentos ficam nos serviços. As verbas internas de custo são definidas pelo engenheiro.</p>';$('#readerContent [data-action="confirm-budget"]').disabled=!!a.errors.length}
 function confirmBudgetImport(){try{if(!budgetAnalysis)throw Error('Selecione o arquivo e confira a prévia.');let next=window.EngefexManager.importBudget(state,project,budgetAnalysis,$('#budgetValue').checked);D.backupValid(next);persist(next,'Orçamento importado com etapas, serviços e composição de valores.');$('#reader').close();location.hash='#activities';render()}catch(e){toast(e.message)}}
 let docAttachments=[],docPending=[],docPreparing=false;
 function documentEditor(record){docAttachments=D.clone(record.attachments||[]);docPending=[];docPreparing=false;$('#fields').innerHTML+='<section class="field full"><h3>Anexos do documento</h3><label>Adicionar arquivos<input id="docAttachments" type="file" multiple></label><div id="documentAttachments"></div><p id="documentAttachmentError" class="red-text"></p></section>';drawDocumentAttachments();$('#docAttachments').onchange=async e=>{let context=editContext;docPreparing=true;try{let batch=[];for(let f of e.target.files)batch.push(await window.LocalFiles.prepare(f));if(context!==editContext||!$('#editor').open)return;docPending.push(...batch);docAttachments.push(...batch.map(f=>({id:f.id,name:f.name,type:f.type})));drawDocumentAttachments()}catch(err){if(context===editContext&&$('#documentAttachmentError'))$('#documentAttachmentError').textContent=err.message}finally{if(context===editContext)docPreparing=false;e.target.value=''}}}
 function drawDocumentAttachments(){let host=$('#documentAttachments');if(!host)return;host.innerHTML=docAttachments.map(f=>'<div class="split-line"><span>'+h(f.name)+'</span><button type="button" class="text-btn red-text" data-withdraw-file="'+h(f.id)+'">Retirar anexo</button></div>').join('');for(let el of host.querySelectorAll('[data-withdraw-file]'))el.onclick=()=>{docAttachments=docAttachments.filter(f=>f.id!==el.dataset.withdrawFile);drawDocumentAttachments()}}
 async function commitDocuments(){if(docPreparing)throw Error('Aguarde a preparação dos anexos.');await window.LocalFiles.put(docPending.filter(f=>docAttachments.some(x=>x.id===f.id)));return D.clone(docAttachments)}
 async function documentFile(id){let r=state.documents.find(r=>r.id===id);if(!r)return;$('#readerTitle').textContent=r.name;$('#readerContent').innerHTML='<div class="reader-page"><p>Carregando anexos…</p></div>';if(!$('#reader').open)$('#reader').showModal();try{let attached=await window.LocalFiles.load((r.attachments||[]).map(f=>f.id));$('#readerContent').innerHTML='<div class="reader-page"><p>'+br(r.text||r.textPages?.join('\n')||'')+'</p><div class="saved-photo-gallery">'+attached.map(f=>'<figure>'+(f.type?.startsWith('image/')?'<img src="'+f.dataURL+'" alt="'+h(f.name)+'">':'')+'<figcaption>'+h(f.name)+'</figcaption><button class="button secondary" type="button" data-download-attached="'+h(f.id)+'">Baixar arquivo</button></figure>').join('')+'</div>'+(attached.length?'':'<p>Sem arquivos anexados.</p>')+edit('documents',id)+'</div>';for(let button of $$('#readerContent [data-download-attached]'))button.onclick=()=>{let f=attached.find(f=>f.id===button.dataset.downloadAttached),bytes=Uint8Array.from(atob(f.dataURL.split(',')[1]),c=>c.charCodeAt(0));download(f.name,new Blob([bytes],{type:f.type}),f.type)}}catch(e){$('#readerContent').textContent=e.message}}
